// Relocation Entry Structure (e.g., ELF Rela format)
typedef struct {
    uint64_t r_offset;  // Relative offset in section needing fixup
    uint64_t r_info;    // Symbol index and type (R_X86_64_64, etc.)
    int64_t r_addend;   // Constant bias stored in object file
} RelocationEntry;

// Linker/Loader Context
uint64_t Object_Base_Address = 0x400000; // Start of the loaded object
uint64_t Symbol_Final_Value = 0x800200;  // Final address of the referenced symbol

RelocationEntry R = {
    .r_offset = 0x1A0,
    .r_addend = 0x0
};

// 1. Calculate Target Memory Location
uint64_t Fixup_Location = Object_Base_Address + R.r_offset; // 0x4001A0

// 2. Calculate Final Absolute Address (S + A)
// S = Symbol Value, A = Addend
uint64_t Final_Address = Symbol_Final_Value + R.r_addend; // 0x800200

// Loader writes Final_Address into memory at Fixup_Location.
